#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

// Returns g = gcd(a, b) and sets x, y such that a*x + b*y = g
ll extgcd(ll a, ll b, ll &x, ll &y) {
    if (b == 0) { x = 1; y = 0; return a; }
    ll x1, y1;
    ll g = extgcd(b, a % b, x1, y1);
    x = y1;
    y = x1 - (a / b) * y1;
    return g;
}

int main(){
    int q;
    cin >> q;
    while (q--) {
        ll a, m;
        cin >> a >> m;
        ll x, y;
        ll g = extgcd(a, m, x, y);
        if (g != 1) {
            cout << "no inverse\n";
        } else {
            ll inv = ((x % m) + m) % m;
            cout << inv << "\n";
        }
    }
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef __int128 lll;

ll extgcd(ll a, ll b, ll &x, ll &y) {
    if (b == 0) { x = 1; y = 0; return a; }
    ll x1, y1;
    ll g = extgcd(b, a % b, x1, y1);
    x = y1;
    y = x1 - (a / b) * y1;
    return g;
}

// Merge x ≡ r1 (mod m1) and x ≡ r2 (mod m2) into x ≡ r (mod m), m = lcm(m1,m2)
bool merge(ll r1, ll m1, ll r2, ll m2, ll &r, ll &m) {
    ll x, y;
    ll g = extgcd(m1, m2, x, y); // m1*x + m2*y = g
    ll diff = r2 - r1;
    if (diff % g != 0) return false;
    ll mod2 = m2 / g;
    ll lcm = m1 / g * m2;
    lll t = ((lll)(diff / g) % mod2) * ((lll)(x % mod2)) % mod2;
    if (t < 0) t += mod2;
    lll res = (lll)r1 + (lll)m1 * t;
    ll modr = (ll)(((res % lcm) + lcm) % lcm);
    r = modr;
    m = lcm;
    return true;
}

int main(){
    int n;
    cin >> n;
    ll r, m;
    cin >> r >> m;
    bool ok = true;
    for (int i = 1; i < n; i++) {
        ll r2, m2;
        cin >> r2 >> m2;
        if (!ok) continue;
        ll nr, nm;
        if (!merge(r, m, r2, m2, nr, nm)) ok = false;
        else { r = nr; m = nm; }
    }
    if (!ok) cout << "no solution\n";
    else cout << r << " " << m << "\n";
}

