int main(){
    int q;
    cin >> q;
    while (q--) {
        ll a, b, c;
        cin >> a >> b >> c;

        // Step 1: compute E = b^c under the convention 0^0 = 1,
        // reduced modulo (MOD - 1) so it is safe to use as an exponent
        // for a via Fermat's little theorem (valid because a < MOD, so
        // a is coprime to MOD whenever a != 0).
        ll E;
        if (c == 0) {
            E = 1;              // b^0 = 1 for every b, including 0^0
        } else if (b == 0) {
            E = 0;              // 0^c = 0 for c > 0
        } else {
            E = power(b, c, MOD - 1); // huge exponent, reduce mod (p-1)
        }

        ll ans;
        if (a == 0) {
            ans = (E == 0) ? 1 : 0; // 0^0 = 1 (convention), 0^(positive) = 0
        } else {
            ans = power(a, E, MOD);
        }
        cout << ans << "\n";
    }
}

