ll pollardRho(ll n) {
    if (n % 2 == 0) return 2;
    static mt19937_64 rng(1234567891ULL); // fixed seed for reproducibility
    ll x = rng() % (n - 2) + 2;
    ll y = x;
    ll c = rng() % (n - 1) + 1;
    ll d = 1;
    while (d == 1) {
        x = (mulmod(x, x, n) + c) % n;
        y = (mulmod(y, y, n) + c) % n;
        y = (mulmod(y, y, n) + c) % n;
        d = __gcd(abs(x - y), n);
    }
    return d != n ? d : pollardRho(n); // retry with new random params on failure
}

void factor(ll n, map<ll,int> &result) {
    if (n == 1) return;
    if (isPrime(n)) { result[n]++; return; }
    ll d = n;
    while (d == n) d = pollardRho(n);
    factor(d, result);
    factor(n / d, result);
}

