    cin >> q;
    while (q--) {
        ll n;
        cin >> n;
        if (n == 1) { cout << "1\n"; continue; }
        map<ll,int> result;
        factor(n, result);
        bool first = true;
        for (auto &pr : result) {
            if (!first) cout << " ";
            cout << pr.first << "^" << pr.second;
            first = false;
