}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main(){
    ll L, R;
    cin >> L >> R;
    if (L < 2) L = 2;

    // Step 1: sieve all primes up to sqrt(R) with a plain Eratosthenes sieve
    ll limit = (ll)sqrt((double)R) + 2;
    while (limit * limit > R + 1) limit--; // trim just in case of fp error
    while ((limit + 1) * (limit + 1) <= R) limit++;
    vector<bool> isComposite(limit + 1, false);
    vector<ll> basePrimes;
    for (ll i = 2; i <= limit; i++) {
        if (!isComposite[i]) {
            basePrimes.push_back(i);
            for (ll j = i * i; j <= limit; j += i) isComposite[j] = true;
        }
    }

    // Step 2: mark composites in the window [L, R] using each base prime
    ll size = R - L + 1;
    vector<bool> windowComposite(size, false);
    for (ll p : basePrimes) {
        ll start = max(p * p, ((L + p - 1) / p) * p); // first multiple of p that is >= L
        for (ll j = start; j <= R; j += p) {
            windowComposite[j - L] = true;
        }
    }

    ll count = 0;
    for (ll i = 0; i < size; i++) {
        ll val = L + i;
        if (!windowComposite[i] && val >= 2) count++;
    }
    cout << count << "\n";
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll MOD = 1000000007LL;
const int MAXN = 1000006;

ll fact[MAXN], invFact[MAXN];

ll power(ll base, ll exp, ll mod) {
    base %= mod;
    if (base < 0) base += mod;
    ll result = 1;
    while (exp > 0) {
        if (exp & 1) result = (__int128)result * base % mod;
        base = (__int128)base * base % mod;
        exp >>= 1;
    }
    return result;
}

void precompute() {
    fact[0] = 1;
    for (int i = 1; i < MAXN; i++) fact[i] = (__int128)fact[i-1] * i % MOD;
    invFact[MAXN - 1] = power(fact[MAXN - 1], MOD - 2, MOD);
    for (int i = MAXN - 2; i >= 0; i--)
        invFact[i] = (__int128)invFact[i+1] * (i + 1) % MOD;
}

ll nCr(int n, int r) {
    if (r < 0 || r > n || n < 0) return 0;
    return (__int128)fact[n] * invFact[r] % MOD * invFact[n-r] % MOD;
}

int main(){
    precompute();
    int q;
    cin >> q;
    while (q--) {
        int a, b;
        cin >> a >> b;
        cout << nCr(a, b) << "\n";
    }
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef unsigned long long ull;
typedef __int128 lll;

int main(){
    ll n;
    int k;
    cin >> n >> k;
    vector<ll> p(k);
    for (auto &x : p) cin >> x;

    // Inclusion-exclusion over all 2^k non-empty subsets of the primes.
    // For a subset S, the numbers in [1,n] divisible by ALL primes in S
    // are exactly the multiples of prod(S); there are floor(n/prod(S)) of
    // them. Add for odd |S|, subtract for even |S|.
    ll answer = 0;
    for (int mask = 1; mask < (1 << k); mask++) {
        lll product = 1;
        int bits = __builtin_popcount(mask);
        bool overflow = false;
        for (int i = 0; i < k; i++) {
            if (mask & (1 << i)) {
                product *= p[i];
                if (product > (lll)n) { overflow = true; break; }
            }
        }
        if (overflow) continue; // product > n means floor(n/product) = 0
        ll cnt = (ll)((lll)n / product);
        if (bits % 2 == 1) answer += cnt;
        else answer -= cnt;
    }
    cout << answer << "\n";
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll MOD = 1000000007LL;
const int MAXN = 2000006;

ll fact[MAXN], invFact[MAXN];

ll power(ll base, ll exp, ll mod) {
    base %= mod;
    if (base < 0) base += mod;
    ll result = 1;
    while (exp > 0) {
        if (exp & 1) result = (__int128)result * base % mod;
        base = (__int128)base * base % mod;
        exp >>= 1;
    }
    return result;
}

void precompute() {
    fact[0] = 1;
    for (int i = 1; i < MAXN; i++) fact[i] = (__int128)fact[i-1] * i % MOD;
    invFact[MAXN - 1] = power(fact[MAXN - 1], MOD - 2, MOD);
    for (int i = MAXN - 2; i >= 0; i--)
        invFact[i] = (__int128)invFact[i+1] * (i + 1) % MOD;
}

ll nCr(int n, int r) {
    if (r < 0 || r > n || n < 0) return 0;
    return (__int128)fact[n] * invFact[r] % MOD * invFact[n-r] % MOD;
