int main(){
    precompute();
    int q;
    cin >> q;
    while (q--) {
        int m, n;
        cin >> m >> n;
        // We want S = sum_{k=0}^{min(m,n)} C(m,k) * C(n,k) mod p.
        // By Vandermonde's identity, C(n,k) = C(n,n-k), so
        // S = sum_k C(m,k) * C(n, n-k) = C(m+n, n)  (Vandermonde convolution).
        // This turns an O(min(m,n)) summation into an O(1) lookup.
        cout << nCr(m + n, n) << "\n";
    }
}
